/// L'entrée d'un index de la table statique.
///
/// # ELLE COMMENCE À ZÉRO, ET CELLE DE HPACK COMMENÇAIT À UN
///
/// §3.1 : « the static table […] is indexed starting at zero ». HPACK réservait
/// le zéro pour dire « rien », et sa première entrée portait l'index un. Un
/// décodeur qui garderait l'habitude de HPACK décalerait toute la table d'un
/// rang — et lirait `:path` là où le pair a écrit `:authority`.
#[must_use]
pub fn entree_statique(index: u64) -> Option<(&'static [u8], &'static [u8])> {
    // Un index venu du fil est un `u64` ; la table est indexée par un `usize`.
    // `usize::MAX` fait manquer le `get` à coup sûr, là où un `try_from` fautif
    // ouvrirait une branche qu'aucune cible de soixante-quatre bits ne peut
    // emprunter.
    let rang = usize::try_from(index).unwrap_or(usize::MAX);
    STATIQUE.get(rang).copied()
}

